    : ''
  // 携带登录 token：C端 App.vue 通过 peekUrlToken 读取后写入本地并即时从地址栏剥离，
  // request.ts 再作为 Authorization: Bearer 注入请求头，实现跳转免登。
  const token = userStore.token
    ? `${separator === '?' ? '&' : '&'}token=${encodeURIComponent(userStore.token)}`
    : ''
  const url = `${H5_BASE}/#${route}${separator}from=handheld${area}${token}`
